// Three invented leads, one per intake source, so the whole workflow can be run before a
// webhook is pointed at anything. They are deliberately different shapes: a website form
// posts flat fields, a forwarded email arrives as a blob of text, a phone note is whatever
// somebody typed. `read the lead` is what makes them the same thing.
return [
  {
    json: {
      _demo: true,
      source: 'website',
      form: {
        full_name: 'Priya Raman',
        email: 'priya@example.com',
        phone: '+44 7700 900111',
        company: 'Northgate Clinics',
        message: 'We need a quote for onboarding 40 staff onto your platform.'
      }
    }
  },
  {
    json: {
      _demo: true,
      source: 'email',
      subject: 'Fwd: support issue with the portal',
      body: 'Forwarded message\nFrom: Tom Auber <tom.auber@example.org>\n' +
            'Phone: 020 7946 0102\n\n' +
            'Our portal login has been failing since the update. Can someone take a look?'
    }
  },
  {
    json: {
      _demo: true,
      source: 'phone',
      note: 'Call from Dana Whitlock at Ferris Group, 07700 900222. ' +
            'Wants a demo before end of month. Email dana.whitlock@example.net'
    }
  }
];

// ZOHO CRM — LEAD ROUTING AND STAGE SWEEP — CONFIG
// Everything you might want to change lives in this one node. Nothing else in either
// workflow needs editing.
//
// The same config node ships in BOTH workflows ("01 lead routing" and "02 stage sweep").
// build.py regenerates both from this one file and validate.py fails if they drift apart,
// so you never paste it between them by hand.
//
// A blank id or key means that step is SKIPPED, never that the run fails. That is what lets
// this be demonstrated on a screen-share before a single Zoho credential exists.

// ---------------------------------------------------------------- Safety
// DRY_RUN ships true. Nothing is created in Zoho until you change it, deliberately.
const DRY_RUN = true;

// ---------------------------------------------------------------- Which Zoho you are on
// Zoho is regional and the data centre is part of the URL. Getting this wrong is the most
// common reason a working integration returns INVALID_TOKEN against a perfectly valid token.
//   US   https://www.zohoapis.com       accounts: https://accounts.zoho.com
//   EU   https://www.zohoapis.eu        accounts: https://accounts.zoho.eu
//   IN   https://www.zohoapis.in        accounts: https://accounts.zoho.in
//   AU   https://www.zohoapis.com.au    accounts: https://accounts.zoho.com.au
//   JP   https://www.zohoapis.jp        accounts: https://accounts.zoho.jp
//   CA   https://www.zohoapis.ca        accounts: https://accounts.zohocloud.ca
const ZOHO_API_BASE      = 'https://www.zohoapis.com';
const ZOHO_ACCOUNTS_BASE = 'https://accounts.zoho.com';
const ZOHO_API_VERSION   = 'v8';

// ---------------------------------------------------------------- Getting in
// A Zoho access token lives for ONE HOUR. Do not paste one here: it will work in the demo
// and stop working before the first real day is out. Register a Self Client or a
// Server-based app at api-console.zoho.com, authorise it once with the scopes below, and
// keep the REFRESH token. These workflows exchange it for a fresh access token at the top of
// every run, which is the difference between an integration that survives and one that has
// to be re-authorised by hand every morning.
//
// Scopes: ZohoCRM.modules.leads.CREATE, ZohoCRM.modules.deals.READ,
//         ZohoCRM.modules.tasks.CREATE, ZohoCRM.coql.READ
//
// All three blank -> both workflows build the exact request and stop in front of it, so you
// can read what they would have sent. They ship blank: this file goes out as a work sample.
const ZOHO_CLIENT_ID     = '';
const ZOHO_CLIENT_SECRET = '';
const ZOHO_REFRESH_TOKEN = '';

// ---------------------------------------------------------------- Do Zoho's own rules fire?
// Zoho runs workflow rules, approvals and blueprint transitions on a record created over the
// API only when you ask it to. An empty list means none of them fire; ['workflow'] means
// workflow rules do.
//
// Leave this EMPTY while Deluge is still doing the routing, or a lead written here is routed
// twice — once by this workflow and once by the rule that used to do it. Turn it on
// deliberately, one rule at a time, as the old ones are retired.
const ZOHO_TRIGGERS = [];

// ---------------------------------------------------------------- The layout
// Leads and Deals both carry an Owner. A blank owner id means the record is created
// unassigned rather than the run failing.
const LEAD_LAYOUT_ID = '';
const OWNERS = [
  { owner: 'Ada',  user_id: '' },
  { owner: 'Ben',  user_id: '' },
  { owner: 'Cara', user_id: '' }
];

// Zoho field API name -> where to read it off the lead. A blank api_name is skipped rather
// than written as an empty field, so a half-mapped org still writes a clean record.
const CUSTOM_FIELDS = [
  { api_name: 'Lead_Source_Detail', from: 'source'  },
  { api_name: 'Enquiry_Type',       from: 'wants'   },
  { api_name: 'Summary',            from: 'summary' }
];

// ---------------------------------------------------------------- Who gets what
// The rule table. First match wins. A rule may match on the intake source, on what the
// person wants, on both — and the last rule matches nothing on purpose, so a lead that fits
// no rule still lands somewhere rather than nowhere.
//
// THIS TABLE IS THE POINT. When routing changes — a new segment, someone leaves, a status
// gets renamed — it is one row here, not a Deluge function somebody has to open.
const ROUTING_RULES = [
  { match: { wants: 'support' },  owner: 'Cara', status: 'Support',         tags: ['support'] },
  { match: { wants: 'quote' },    owner: 'Ben',  status: 'Quote Requested', tags: ['quote'] },
  { match: { wants: 'demo' },     owner: 'Ben',  status: 'Attempted',       tags: ['demo'] },
  { match: { source: 'phone' },   owner: 'Ben',  status: 'Attempted',       tags: ['phone'] },
  { match: { source: 'email' },   owner: 'Ada',  status: 'Attempted',       tags: ['email'] },
  { match: { source: 'website' }, owner: 'Ada',  status: 'Attempted',       tags: ['website'] },
  { match: {},                    owner: 'Ada',  status: 'Attempted',       tags: ['unrouted'] }
];

// On every lead this workflow writes. The routing rule adds its own.
const BASE_TAGS = ['automation-intake'];

// ---------------------------------------------------------------- The stage sweep
// The rule workflow 02 enforces:
//
//   NO OPEN DEAL SHOULD SIT IN A STAGE WITHOUT THE NEXT ACTION THAT STAGE CALLS FOR.
//
// Zoho's own workflow rules fire on a stage CHANGE. A deal that never moved never fired
// anything, and that is exactly the deal that goes quiet. This runs on a schedule and asks
// every open deal, so the ones nothing fired for are the ones it catches.
const OPEN_STAGES = ['Qualification', 'Needs Analysis', 'Proposal', 'Negotiation'];

// Per stage: the task to create when an open deal has no next action, how soon it is due,
// and how long a deal may sit in that stage before it is called stalled.
const STAGE_ACTIONS = [
  { stage: 'Qualification',  task: 'Qualify: confirm budget, authority and timeline', due_in_days: 2, stale_after_days: 7 },
  { stage: 'Needs Analysis', task: 'Book the scoping call',                           due_in_days: 3, stale_after_days: 10 },
  { stage: 'Proposal',       task: 'Chase the proposal',                              due_in_days: 3, stale_after_days: 14 },
  { stage: 'Negotiation',    task: 'Agree the next step in writing',                  due_in_days: 2, stale_after_days: 10 }
];

// A deal whose next action is ALREADY OVERDUE does not get a second task piled on top of it.
// It is escalated to the digest instead. Stacking tasks is how a pipeline stops being
// trusted, and once nobody trusts it, "nothing falls through the cracks" is over.
const ESCALATE_OVERDUE = true;

// How many deals to read in one run. Anything past this is reported, never silently dropped.
const DEAL_PAGE_LIMIT = 200;

// ---------------------------------------------------------------- Notifications
// Optional. Blank -> nothing is posted and the run still completes. Any endpoint that
// accepts a JSON POST: Slack, Teams, Zoho Cliq, a webhook of your own.
const NOTIFY_WEBHOOK_URL  = '';
const NOTIFY_ON_NEW_LEAD  = true;
const NOTIFY_ON_DIGEST    = true;

// ---------------------------------------------------------------- derived — do not edit
const ZOHO_AUTH_READY = ZOHO_CLIENT_ID.trim() !== '' &&
                        ZOHO_CLIENT_SECRET.trim() !== '' &&
                        ZOHO_REFRESH_TOKEN.trim() !== '';

const SETTINGS = {
    dry_run: DRY_RUN === true,
    zoho_api_base: ZOHO_API_BASE.replace(/\/+$/, ''),
    zoho_accounts_base: ZOHO_ACCOUNTS_BASE.replace(/\/+$/, ''),
    zoho_api_version: ZOHO_API_VERSION,
    zoho_client_id: ZOHO_CLIENT_ID,
    zoho_client_secret: ZOHO_CLIENT_SECRET,
    zoho_refresh_token: ZOHO_REFRESH_TOKEN,
    zoho_triggers: ZOHO_TRIGGERS,
    lead_layout_id: LEAD_LAYOUT_ID,
    owners: OWNERS,
    custom_fields: CUSTOM_FIELDS,
    routing_rules: ROUTING_RULES,
    base_tags: BASE_TAGS,
    open_stages: OPEN_STAGES,
    stage_actions: STAGE_ACTIONS,
    escalate_overdue: ESCALATE_OVERDUE === true,
    deal_page_limit: DEAL_PAGE_LIMIT,
    notify_webhook_url: NOTIFY_WEBHOOK_URL,
    notify_on_new_lead: NOTIFY_ON_NEW_LEAD === true,
    notify_on_digest: NOTIFY_ON_DIGEST === true,
    // derived flags — never test a key's emptiness downstream, test the flag
    zoho_auth_ready: ZOHO_AUTH_READY,
    zoho_enabled: ZOHO_AUTH_READY && DRY_RUN !== true,
    notify_enabled: NOTIFY_WEBHOOK_URL.trim() !== '' && DRY_RUN !== true
};

// config sits IN the data path, so it must not swallow the items passing through it. It runs
// once per incoming item and passes that item's payload along untouched under `lead`, so
// three demo leads in is three leads out — not one settings object.
//
// A trigger that carries no payload (the schedule, the manual run in workflow 02) still
// produces one item, so `$('config').first().json` always resolves.
const incoming = $input.all().length ? $input.all().map((i) => i.json || {}) : [{}];
return incoming.map((lead) => ({ json: Object.assign({}, SETTINGS, { lead: lead }) }));

// One node turning any intake shape into one lead shape. A website form posts flat fields,
// a forwarded email is a blob of text, a phone note is whatever somebody typed — and
// everything downstream reads the same six keys.
//
// This is the node that makes the rest of the workflow reusable. Add a fourth source by
// adding a branch here, not by copying the workflow.
const EMAIL_RE = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/;
const PHONE_RE = /(\+?\d[\d\s().-]{7,}\d)/;

function firstMatch(text, re) {
  const m = String(text || '').match(re);
  return m ? m[0].trim() : '';
}

function wantsFrom(text) {
  const t = String(text || '').toLowerCase();
  if (/\b(support|broken|failing|error|bug|not working|issue)\b/.test(t)) return 'support';
  if (/\b(quote|pricing|price|cost|proposal)\b/.test(t)) return 'quote';
  if (/\b(demo|walkthrough|see it|trial)\b/.test(t)) return 'demo';
  return '';
}

function nameFrom(text) {
  const m = String(text || '').match(/(?:from|call from|caller)[:\s]+([A-Z][a-z]+ [A-Z][a-z]+)/i);
  if (m) return m[1];
  const n = String(text || '').match(/\b([A-Z][a-z]+ [A-Z][a-z]+)\b/);
  return n ? n[1] : '';
}

function companyFrom(text) {
  const m = String(text || '').match(/\bat ([A-Z][A-Za-z&.' -]{2,40}?)(?:[,.]|\s+\d|$)/);
  return m ? m[1].trim() : '';
}

return $input.all().map((item) => {
  const envelope = item.json || {};

  // `config` passes each incoming payload through under `lead`, so unwrap that first. A
  // webhook then nests the posted JSON one level further, under `body`. Both are unwrapped
  // here so the rest of this node never has to know which trigger fired.
  let raw = (envelope.lead && typeof envelope.lead === 'object') ? envelope.lead : envelope;
  if (raw.body && typeof raw.body === 'object' && !Array.isArray(raw.body)) raw = raw.body;

  const source = String(raw.source || 'unknown').toLowerCase();

  let name = '', email = '', phone = '', company = '', summary = '';

  if (source === 'website') {
    const f = raw.form || {};
    name = f.full_name || f.name || '';
    email = f.email || '';
    phone = f.phone || '';
    company = f.company || '';
    summary = f.message || '';
  } else if (source === 'email') {
    const body = raw.body || '';
    email = firstMatch(body, EMAIL_RE);
    phone = firstMatch(body, PHONE_RE);
    name = nameFrom(body);
    company = companyFrom(body);
    summary = String(raw.subject || '') + (body ? ' — ' + body.split('\n').pop() : '');
  } else {
    const note = raw.note || raw.body || raw.message || '';
    email = firstMatch(note, EMAIL_RE);
    phone = firstMatch(note, PHONE_RE);
    name = nameFrom(note);
    company = companyFrom(note);
    summary = note;
  }

  const parts = String(name || '').trim().split(/\s+/);
  const lastName = parts.length > 1 ? parts.slice(1).join(' ') : (parts[0] || '');
  const firstName = parts.length > 1 ? parts[0] : '';

  // Zoho's Leads module refuses a record with no Last_Name, and there is no point routing a
  // lead nobody can reply to. Both are checked here so the failure is one named STOP rather
  // than a 400 from Zoho three nodes later.
  const reachable = email !== '' || phone !== '';
  const named = lastName !== '';
  const looksLikeBot = /\b(seo services|guest post|backlink|crypto|loan offer)\b/i
    .test(String(summary));

  return {
    json: {
      _demo: raw._demo === true,
      _ok: reachable && named && !looksLikeBot,
      _why: !named ? 'no name to file it under'
        : !reachable ? 'no email and no phone — nobody could reply'
        : looksLikeBot ? 'reads as spam' : '',
      source,
      first_name: firstName,
      last_name: lastName,
      full_name: name,
      email,
      phone,
      company,
      summary: String(summary || '').trim().slice(0, 2000),
      wants: wantsFrom(summary)
    }
  };
});

// The lead was dropped on purpose, and this node exists so that is visible in the execution
// list rather than a run that quietly produced nothing. `_reason` says which check failed:
// no name to file it under, no way to reply, or it reads as spam.
return $input.all().map((i) => ({
  json: {
    _outcome: 'dropped',
    _reason: i.json._why || 'did not pass the intake check',
    source: i.json.source,
    email: i.json.email,
    phone: i.json.phone,
    summary: String(i.json.summary || '').slice(0, 200)
  }
}));

// First rule that matches wins. A lead that fits no rule still lands on the last rule, which
// matches nothing on purpose — never nowhere. The chosen rule sets the owner, the Zoho lead
// status and the tags it carries.
//
// `_routed_by` records WHICH rule decided, so a run that filed something oddly can be
// explained without re-reading the table.
const cfg = $('config').first().json;

const ownerIds = {};
for (const o of cfg.owners || []) ownerIds[o.owner] = o.user_id;

function matches(rule, lead) {
  const m = rule.match || {};
  if (m.source && m.source !== lead.source) return false;
  if (m.wants && m.wants !== lead.wants) return false;
  return true;
}

return $input.all().map((item) => {
  const lead = item.json || {};
  const rules = cfg.routing_rules || [];

  let chosen = null;
  for (const rule of rules) { if (matches(rule, lead)) { chosen = rule; break; } }
  if (!chosen) chosen = rules[rules.length - 1] || {};

  const tags = [];
  for (const t of (cfg.base_tags || []).concat(chosen.tags || [])) {
    if (tags.indexOf(t) < 0) tags.push(t);
  }

  return {
    json: Object.assign({}, lead, {
      owner: chosen.owner || '',
      owner_user_id: ownerIds[chosen.owner] || '',
      status: chosen.status || 'Attempted',
      tags,
      _routed_by: (chosen.match && Object.keys(chosen.match).length)
        ? JSON.stringify(chosen.match)
        : 'the last rule (matches anything)'
    })
  };
});

// The whole Zoho request, assembled as one object before anything is sent. Building it here
// rather than in the HTTP node means the exact body can be read on a STOP node when no
// credential is configured — which is what makes this demoable before the client has created
// an API client at all.
//
// Zoho specifics worth knowing:
//   * POST /crm/v8/Leads takes { data: [ ... ], trigger: [ ... ] }, up to 100 records.
//   * `trigger` decides whether Zoho's OWN workflow rules, approvals and blueprints fire.
//     Empty means none of them do. See ZOHO_TRIGGERS in config.
//   * Owner and Layout are lookups: { id: '...' }, not names.
//   * A blank id is omitted entirely. Zoho rejects { id: '' } rather than ignoring it.
const cfg = $('config').first().json;
const base = cfg.zoho_api_base + '/crm/' + cfg.zoho_api_version;

return $input.all().map((item) => {
  const lead = item.json || {};

  const record = {
    Last_Name: lead.last_name,
    Lead_Status: lead.status,
    Lead_Source: 'Automation intake',
    Description: lead.summary
  };

  if (lead.first_name) record.First_Name = lead.first_name;
  if (lead.email) record.Email = lead.email;
  if (lead.phone) record.Phone = lead.phone;
  if (lead.company) record.Company = lead.company;
  // Zoho refuses a record whose Company is empty on the default layout.
  if (!record.Company) record.Company = lead.full_name || lead.last_name;

  if (lead.owner_user_id) record.Owner = { id: lead.owner_user_id };
  if (cfg.lead_layout_id) record.Layout = { id: cfg.lead_layout_id };
  if ((lead.tags || []).length) record.Tag = lead.tags.map((t) => ({ name: t }));

  for (const f of cfg.custom_fields || []) {
    if (!f.api_name) continue;
    const v = lead[f.from];
    if (v !== undefined && v !== null && String(v) !== '') record[f.api_name] = v;
  }

  return {
    json: Object.assign({}, lead, {
      _zoho: {
        url: base + '/Leads',
        body: { data: [record], trigger: cfg.zoho_triggers || [] }
      }
    })
  };
});

// Zoho is not configured (DRY_RUN is still true, or one of the three OAuth values is blank).
// Nothing was written — and this node's output IS the result: the exact request body that
// would have gone to Zoho, and where the lead was routed.
//
// This is the node to open on a screen-share. It is the whole demo: real routing, a real
// Zoho payload, and nothing leaving the building.
const cfg = $('config').first().json;

return $input.all().map((i) => ({
  json: {
    _outcome: 'preview — nothing written',
    _reason: cfg.dry_run
      ? 'DRY_RUN is true — set it to false in config once the OAuth values are filled in'
      : 'ZOHO_CLIENT_ID / ZOHO_CLIENT_SECRET / ZOHO_REFRESH_TOKEN is blank',
    routed_to: i.json.owner,
    lead_status: i.json.status,
    tags: i.json.tags,
    routed_by: i.json._routed_by,
    would_post_to: i.json._zoho ? i.json._zoho.url : null,
    would_post: i.json._zoho ? i.json._zoho.body : null
  }
}));

// Reads the access token out of the refresh-token exchange and puts it back on every lead,
// so the write node downstream still has one item per lead rather than one item per token.
//
// Zoho returns HTTP 200 with an `error` key in the body when a refresh fails — an expired or
// revoked refresh token, the wrong data centre, a client id registered in another region. A
// node that only checks the status code treats that as success and then fails confusingly
// later with INVALID_TOKEN, which is the most common way a Zoho integration breaks quietly.
// So the body is checked here, explicitly.
const res = $input.first().json || {};

if (res.error || !res.access_token) {
  return [{
    json: {
      _authed: false,
      _why: res.error ? 'Zoho refused the refresh: ' + res.error
                      : 'Zoho returned no access_token',
      _hint: res.error === 'invalid_client'
        ? 'client id/secret belong to a different data centre than ZOHO_ACCOUNTS_BASE'
        : res.error === 'invalid_code'
        ? 'the refresh token has been revoked, or was issued for different scopes'
        : 'check ZOHO_ACCOUNTS_BASE matches the region the app was registered in',
      _response: res
    }
  }];
}

// One item per lead again, each carrying the token it will be written with.
return $('build the Zoho payload').all().map((item) => ({
  json: Object.assign({}, item.json, {
    _authed: true,
    _access_token: res.access_token,
    _expires_in: res.expires_in || 3600
  })
}));

// The refresh-token exchange failed, so nothing downstream ran. This is a named stop rather
// than a swallowed error because an expired refresh token is the most common way a Zoho
// integration dies quietly: every run "succeeds", nothing is ever written, and nobody notices
// until someone asks where the week's leads went.
//
// `_hint` is the thing to read first — it maps Zoho's terse error to the cause.
return $input.all().map((i) => ({
  json: {
    _outcome: 'not authenticated — nothing written',
    _reason: i.json._why || 'Zoho refused the refresh token',
    _hint: i.json._hint || 'check ZOHO_ACCOUNTS_BASE matches the data centre the app was registered in',
    zoho_response: JSON.stringify(i.json._response || i.json).slice(0, 600)
  }
}));

// Filed in Zoho. Zoho answers a bulk create with one result per record, each carrying its
// own code — so a 200 on the request does NOT mean every record was accepted. Each result is
// read individually here, and anything that is not SUCCESS is reported as a failure even
// though the HTTP call succeeded.
return $input.all().map((i) => {
  const j = i.json || {};
  const results = (j.data && Array.isArray(j.data)) ? j.data : [];
  const first = results[0] || {};
  const ok = String(first.code || '').toUpperCase() === 'SUCCESS';

  return {
    json: {
      _outcome: ok ? 'filed in Zoho CRM' : 'Zoho accepted the request but rejected the record',
      _reason: ok
        ? 'lead created'
        : (first.message || first.code || 'no per-record result returned'),
      zoho_id: (first.details && first.details.id) || '',
      zoho_code: first.code || '',
      // Anything past the first record, when a run ever batches more than one.
      others: results.slice(1).map((r) => ({ code: r.code, message: r.message }))
    }
  };
});

// Zoho refused the write. This node exists so the refusal is a visible step with the response
// on it, rather than a run that half-succeeded and said nothing. Read `zoho_response`.
//
// The three that actually happen: INVALID_TOKEN (wrong data centre, or the access token
// expired mid-run), MANDATORY_NOT_FOUND (the layout needs a field this payload does not
// send), and INVALID_DATA (a picklist value that does not exist in the org — most often a
// Lead_Status from ROUTING_RULES that nobody created in Zoho).
return $input.all().map((i) => {
  const j = i.json || {};
  const err = j.error || j;
  const detail = (err && (err.message || err.description || err.error)) || j;
  return {
    json: {
      _outcome: 'write failed',
      _reason: 'Zoho rejected the lead write — nothing was filed for this lead',
      routed_to: j.owner || '',
      zoho_response: typeof detail === 'string' ? detail : JSON.stringify(detail).slice(0, 600)
    }
  };
});

// The notification that goes out when a lead is routed — their third named automation.
//
// It is composed from the routing decision, not from the Zoho response, on purpose: the team
// should be told who owns a lead even on a run where the Zoho write later fails. A
// notification that only fires on success is a notification that goes silent exactly when
// somebody needs to know.
const cfg = $('config').first().json;

const leads = $input.all().map((i) => i.json || {});
const lines = leads.map((l) => [
  'New lead — ' + (l.full_name || l.last_name || 'unnamed'),
  '  via ' + l.source + (l.company ? ' · ' + l.company : ''),
  '  owner: ' + (l.owner || 'unassigned') + ' · status: ' + l.status,
  '  matched: ' + l._routed_by,
  '  ' + (l.email || l.phone || 'no contact detail')
].join('\n'));

const text = lines.join('\n\n');

return [{
  json: {
    _outcome: 'notification composed',
    _count: leads.length,
    _send: cfg.notify_enabled && cfg.notify_on_new_lead,
    text,
    _notify: { url: cfg.notify_webhook_url, body: { text } }
  }
}];

// No notification was posted — NOTIFY_WEBHOOK_URL is blank, DRY_RUN is still true, or the
// relevant NOTIFY_ON_* switch is off. The message that would have been sent is on this node,
// so the wording can be agreed before anybody wires a Slack webhook.
const cfg = $('config').first().json;
return $input.all().map((i) => ({
  json: {
    _outcome: 'notification not sent',
    _reason: cfg.notify_webhook_url.trim() === ''
      ? 'NOTIFY_WEBHOOK_URL is blank — nothing to post to'
      : cfg.dry_run
      ? 'DRY_RUN is true'
      : 'the NOTIFY_ON_ switch for this workflow is off',
    would_post_to: i.json._notify ? i.json._notify.url : null,
    would_say: i.json.text || ''
  }
}));

// The notification was accepted by the endpoint. Recorded as its own step so an execution
// shows plainly whether the team was told, separately from whether Zoho was written.
return [{
  json: {
    _outcome: 'team notified',
    _reason: 'the notification endpoint accepted the post'
  }
}];

// The notification endpoint refused the post. Named, with the response on it, because a
// silently dropped notification is indistinguishable from "there was nothing to tell you" —
// and those two need to look different in the execution list.
//
// Note what this node does NOT do: it does not fail the run. Zoho has already been written
// by this point, and losing a Slack message is not a reason to lose the lead.
return $input.all().map((i) => {
  const j = i.json || {};
  const err = j.error || j;
  const detail = (err && (err.message || err.description || err.error)) || j;
  return {
    json: {
      _outcome: 'notification failed',
      _reason: 'the notification endpoint refused the post — the CRM write is unaffected',
      response: typeof detail === 'string' ? detail : JSON.stringify(detail).slice(0, 400)
    }
  };
});
